Lemma lp_lift_src K R M model LBX cr sp r fb cat p s str sm en k e M1 model1 X1 s1 sm1 en1 k1 e1 cr1 M2 qc2 de2 rem2 sm2 h q :
  PEUCLPD.pctx L HI P K R M model LBX cr sp r fb cat p s str sm en k e ->
  PEUCLPD.lmem L HI P R M model LBX cr sp fb cat p s str sm en k e M1 model1 X1 s1 sm1 en1 k1 e1 cr1 ->
  0 <= h -> 12288 + 2048 * h + 128 <= 32768 ->
  L5C.hpres L (PEC.owned s1 en1 k1 ++ LBX) (sp - 128) (PMSP.pm_scr h) (PMSP.W_src AD fb (PM.p_src s1) ++ []) M1 M2 ->
  PM.parser_at RSEGS AD PMSP.T3 PMSP.T4 M2 (PMSP.o_p AD fb) (PMSP.o_is AD fb) (PMPS.with_src s1 (PM.SRC qc2 de2 rem2)) ->
  PM.iss_at RSEGS AD PMSP.T3 M2 (PMSP.o_is AD fb) str sm2 ->
  PMSP.src_step (PM.p_src s1) (PM.SRC qc2 de2 rem2) sm1 sm2 ->
  hi_heap HI (PEC.owned s1 en1 k1 ++ LBX) cr1 M2 (m_vmmaps model1) ->
  PECS.cwin RSEGS M2 p (PM.SRC qc2 de2 rem2) sm2 ->
  (s_more X1 = true -> s_done X1 = false -> PEC.pos_of p (PM.SRC qc2 de2 rem2) sm2 = q) ->
  PEUCLPD.lmem L HI P R M model LBX cr sp fb cat p s str sm en k e M2 model1 (w_pos q X1) (PMPS.with_src s1 (PM.SRC qc2 de2 rem2)) sm2 en1 k1 e1 cr1
